// InvestmentPlans.js (Frontend - React)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
//import './InvestmentPlans.css'; // Create this CSS file
import { Link } from 'react-router-dom';

function InvestmentPlans() {
    const [plans, setPlans] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchInvestmentPlans = async () => {
            try {
                const response = await axios.get('/investment-plans'); // Your backend API endpoint
                setPlans(response.data);
            } catch (error) {
                console.error("Error fetching investment plans:", error);
                setError("Failed to load investment plans.");
            } finally {
                setLoading(false);
            }
        };

        fetchInvestmentPlans();
    }, []);

    if (loading) {
        return <div>Loading investment plans...</div>;
    }

    if (error) {
        return <div>Error: {error}</div>;
    }

    return (
        <>
        <div className="main-container">
            <div className="sidebar">
                <Link to="/home">Home </Link>
                <Link to="/loans">Loan </Link>
                <Link to="/balance">Balance </Link>
                <Link to="/insurance">Insurance </Link>
                <Link to="/tranfer">Payment tranfer </Link>
		<Link to="/profile">Profile </Link>

            </div>
            </div>
        <div className="investment-plans-container">
            <h2>Investment Plans</h2>
            <div className="plans-grid"> {/* Use CSS Grid for layout */}
                {plans.map((plan) => (
                    <div key={plan.id} className="investment-plan">
                        <h3>{plan.name}</h3>
                        <p>Minimum Investment: ${plan.minInvestment}</p>
                        <p>Returns: {plan.returns}%</p>
                        <p>Risk Level: {plan.riskLevel}</p>
                        {/* Add more plan details as needed */}
                        <button>Invest Now</button> {/* Placeholder button */}
                    </div>
                ))}
            </div>
        </div>
        </>
    );
}


export default InvestmentPlans;
